function videoDemo(){return{version:1,domain:'video',title:'Live Production — 映像システム',canvas:{width:4800,height:3200},groups:[{id:'cameras',name:'CAMERA SOURCES',subtitle:'撮影・入力',x:40,y:40,w:560,h:930},{id:'control',name:'LIVE SWITCHING',subtitle:'スイッチング・配信',x:700,y:40,w:350,h:930},{id:'outputs',name:'PROGRAM & MULTIVIEW',subtitle:'映像出力',x:1150,y:40,w:350,h:930}],nodes:[{id:'cam1',model:'v_z150',name:'PXW-Z150 · Camera 1',group:'cameras',x:70,y:135},{id:'cam2',model:'v_a6400',name:'α6400 · Camera 2',group:'cameras',x:350,y:135},{id:'cam3',model:'v_hero12',name:'HERO12 + Mod · Camera 3',group:'cameras',x:70,y:545},{id:'slides',model:'v_slides_pc',name:'スライド・上映PC',group:'cameras',x:350,y:545},{id:'switch',model:'v_atem_mini_extreme_iso_g2',name:'ATEM Mini Extreme ISO G2',group:'control',x:760,y:135},{id:'stream',model:'v_stream_pc',name:'配信PC · OBS / Zoom',group:'control',x:760,y:650},{id:'monitor',model:'v_monitor',name:'マルチビューモニター',group:'outputs',x:1210,y:135},{id:'projector',model:'v_projector',name:'プログラム・プロジェクター',group:'outputs',x:1210,y:570}],edges:[['cam1','hdmi','switch','hdmiin1','HDMI',10],['cam2','hdmi','switch','hdmiin2','HDMI_MICRO',5],['cam3','hdmi','switch','hdmiin3','HDMI_MICRO',5],['slides','hdmi','switch','hdmiin4','HDMI',3],['switch','hdmiout1','monitor','hdmi','HDMI',3],['switch','hdmiout2','projector','hdmi','HDMI',10],['switch','webcam1','stream','uvc1','UVC',1]].map((e,i)=>({id:'ve'+i,from:e[0],fp:e[1],to:e[2],tp:e[3],type:e[4],length:e[5],format:'1080p59.94'}))}}
function videoFormats(a,b){return a.formats&&b.formats?a.formats.filter(f=>b.formats.includes(f)):[]}
function videoEdgeError(a,b,e){if(!['video','uvc'].includes(a.signal))return null;if(!videoFormats(a,b).length)return '共通の解像度・フレームレートがありません';if(e?.format&&!videoFormats(a,b).includes(e.format))return '設定した映像フォーマットに対応していません';return null}
function videoFormatControl(edge){let a=getport(edge.from,edge.fp),b=getport(edge.to,edge.tp),fm=videoFormats(a,b);if(!fm.length)return '';return `<div class="label">映像フォーマット</div><select id="videoformat" aria-label="映像フォーマット">${fm.map(f=>`<option value="${f}" ${f===(edge.format||fm[0])?'selected':''}>${f}</option>`).join('')}</select><p class="source">このケーブルで送る信号の設定。実機の出力設定も合わせてください。HDMI / SDIの埋め込み音声は同じ1本で伝送します。</p>`}
function bindVideoFormat(edge){let el=document.querySelector('#videoformat');if(el)el.onchange=()=>{remember();edge.format=el.value;render()}}
function initializeVideoWorkspace(){
 document.body.classList.toggle('video-mode',isVideo);
 document.querySelectorAll('[data-mode]').forEach(el=>{let current=(el.dataset.mode==='video')===isVideo;el.classList.toggle('active',current);if(current)el.setAttribute('aria-current','page');el.onclick=()=>saveBeforeSwitch()});
 if(!isVideo)return;
 document.title='PATCHFLOW | 映像配線エディター';document.querySelector('.version').textContent='v0.8 · VIDEO';
 document.querySelector('#sixpreset').textContent='映像デモ';document.querySelector('#sixpreset').onclick=()=>{remember();state=demo();selected='switch';selectedEdge=null;pending=null;rewire=null;insertDraft=null;render();fitCanvas();toast('映像デモを配置しました（↶で戻せます）')};
 document.querySelector('#emptycanvas h2').textContent='ここから、映像をつなごう。';
 if(document.querySelector('.future'))document.querySelector('.future').innerHTML='▧ <div>VIDEO WORKSPACE<small>HDMI / Micro HDMI / SDI / USB映像</small></div>';
 document.querySelector('#modelscope').textContent='映像ケーブルを選択すると、詳細で解像度・フレームレートを設定できます。';
 document.querySelector('#domainlegend').innerHTML='HDMI <i class="legend" style="background:#68baf0"></i> SDI <i class="legend" style="background:#c19bf4"></i> USB映像 <i class="legend" style="background:#78dbce"></i>';
}
function defaultVideoFormat(a,b){let fm=videoFormats(a,b);return fm.includes('1080p59.94')?'1080p59.94':fm[0]}
function videoGraphWarnings(project){let warnings=[];for(let n of project.nodes){let m=models[n.model];if(m.category!=='converter')continue;let ins=project.edges.filter(e=>e.to===n.id),outs=project.edges.filter(e=>e.from===n.id);for(let out of outs){let inId=m.name.includes('BiDirectional')?(out.fp.startsWith('hdmi')?'sdiin':'hdmiin'):m.ports.find(p=>p.dir==='in')?.id;let input=ins.find(e=>e.tp===inId);if(!input)warnings.push(n.name+': '+out.fp+'の変換元入力が未接続');else if(input.format&&out.format&&input.format!==out.format)warnings.push(n.name+': 変換器は解像度・フレームレートを変更できません')}}for(let edge of project.edges){if(['HDMI','HDMI_MICRO'].includes(edge.type)&&edge.length>=10)warnings.push('HDMI '+edge.length+'m: 光・アクティブ等の長距離対応を確認してください')}return warnings}
